python
def priorityBasketEvenKeyCensus(readings, k):
    a=readings
    out=[]
    import heapq
    heap=a[:]
    heapq.heapify(heap)
    while heap: out.append(heapq.heappop(heap))
    return sum(x%2==0 for x in out)


